contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256 tokenId,
        address from,
        address to,
        uint256 amount,
        bytes memory data
    ) public payable {
        require(from != address(0) && to != address(0));
        require(from != to);

        // Ensure the token exists by creating one with transferability false.
        c.createGameItem("item", "uri", false, false, 0, 0, 0);

        uint256 itemCount = c.uniqueTokensOutstanding();
        require(tokenId < itemCount);

        // Sanity: token starts non-transferable.
        ( , , bool transferableBefore, , , ) = c.allGameItemAttributes(tokenId);
        require(!transferableBefore);

        // Make the token transferable.
        c.adjustTransferability(tokenId, true);

        bool reverted;
        try c.safeTransferFrom(from, to, tokenId, amount, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After enabling transferability, safeTransferFrom must not revert.
        // (Exceptions for invalid inputs are excluded by the requires above.)
        assert(!reverted);
    }

    receive() external payable {}
}

